'use strict';
// Actual renderer files + an explicitly synthetic finite preload double.
// This suite does not test blockchain integrations or real cryptographic signing.
const fs=require('node:fs/promises'),path=require('node:path'),assert=require('node:assert/strict'),http=require('node:http'),{createRequire}=require('node:module');
const candidate=path.resolve(__dirname,'../..'),ui=path.join(candidate,'ui');
const deps=createRequire(path.join(candidate,'package.json')),{chromium}=deps('@playwright/test'),qrcode=deps('qrcode');
const {installFixture}=require('./fixture-bridge.cjs');
const {auditVisuals}=require('./visual-audit.cjs');
const {measurePixelContrast}=require('./pixel-contrast.cjs');
const pixelMeasurements=[];
const {createHash}=require('node:crypto');
async function sourceSnapshot(){return Object.fromEntries(await Promise.all(['index.html','style.css','shell.js','routes.js','chooser.js','chooser.css','black.css','portfolio.js','workspace.js','private-view.js','note-discovery.js','assets.js'].map(async name=>[name,createHash('sha256').update(await fs.readFile(path.join(ui,name))).digest('hex')])));}
const output=path.resolve(process.env.DRIVEKEY_UI_TEST_OUTPUT||process.env.DRIVEKEY_TEST_OUTPUT||path.join(candidate,'verification/ui')),passphrase='Fixture-only UI passphrase 2026!';
const suites=[],results=[];
function test(name,screens,run,options={}){suites.push({name,screens,run,options});}
const sampleRecipient='0x3333333333333333333333333333333333333333';
const escapeId=value=>String(value).replace(/["\\]/g,'\\$&');
async function visible(page,selector){await page.locator(selector).waitFor({state:'visible',timeout:8000});}
async function navigate(page,name){const button=page.locator('button[data-view="'+name+'"]').first();await button.click();await visible(page,'section[data-page="'+name+'"]');}
async function idle(page){await page.waitForFunction(()=>{const w=document.querySelector('#working');return !w||w.hidden;});}
async function snapshot(page){return page.evaluate(()=>window.__fixture.snapshot());}
async function queue(page,method,...replies){return page.evaluate(({method,replies})=>window.__fixture.queue(method,...replies),{method,replies});}
async function activate(page,id='11111111-1111-4111-8111-111111111111'){
  await navigate(page,'vault');const row=page.locator('[data-wallet-id="'+escapeId(id)+'"]');await row.waitFor();
  const button=row.getByRole('button',{name:/^Use wallet$|^Selected$/});if(await button.isEnabled())await button.click();await idle(page);
  assert.equal((await snapshot(page)).activeId,id);
}
async function verifyBackup(page){await navigate(page,'security');await page.fill('#backup-pass',passphrase);await page.locator('#backup-form button[type="submit"],#backup-form button').first().click();await idle(page);assert.equal((await snapshot(page)).wallets.find(w=>w.activeId===w.id||w.id==='11111111-1111-4111-8111-111111111111').backupVerified,true);}
async function choose(page,selector,value){const field=page.locator(selector);const disclosure=field.locator('xpath=ancestor::details[1]');if(await disclosure.count()&&await disclosure.getAttribute('open')===null)await disclosure.locator('summary').first().click();const id=await field.getAttribute('id');const index=await field.evaluate((element,wanted)=>[...element.options].findIndex(o=>o.value===wanted),value);assert.ok(index>=0,'Missing selectable value '+value);const trigger=page.locator('[data-chooser-for="'+id+'"]');await trigger.click();await page.locator('.dk-choice-menu:not(.closing) [data-index="'+index+'"]').click();assert.equal(await field.inputValue(),value);}
async function fillPayment(page){await navigate(page,'payments');await choose(page,'#payment-chain','sepolia');await choose(page,'#payment-asset','ETH');await page.fill('#payment-recipient',sampleRecipient);await page.fill('#payment-amount','0.001');}
async function preparePayment(page){await fillPayment(page);await page.locator('#payment-form button[type="submit"]').click();await idle(page);await visible(page,'#review-loaded');return (await snapshot(page)).prepared;}
async function text(page,selector='body'){return (await page.locator(selector).innerText()).replace(/\s+/g,' ');}
async function screen(page,name){await page.evaluate(async()=>{await document.fonts.ready;document.querySelector('[data-page]:not([hidden]) h1')?.focus({preventScroll:true});window.scrollTo(0,0);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});await page.screenshot({path:path.join(output,'fixture-'+name+'.png'),fullPage:true});}
async function ensureNoHorizontalOverflow(page){const dims=await page.evaluate(()=>({scroll:document.documentElement.scrollWidth,view:innerWidth}));assert.ok(dims.scroll<=dims.view+1,JSON.stringify(dims));}

