async function main(){
  if(process.argv.includes('--list')){console.log(JSON.stringify(suites.map(s=>({name:s.name,screens:s.screens})),null,2));return;}
  await fs.mkdir(output,{recursive:true});
  const scratchRoot=path.join(candidate,'work/ui-tests');await fs.mkdir(scratchRoot,{recursive:true});
  const realCandidate=await fs.realpath(candidate),realScratchRoot=await fs.realpath(scratchRoot);
  assert.ok(realScratchRoot.startsWith(realCandidate+path.sep),'UI test scratch must remain inside this candidate.');
  const scratch=await fs.mkdtemp(path.join(realScratchRoot,'renderer-'));
  process.env.TEMP=scratch;process.env.TMP=scratch;process.env.TMPDIR=scratch;
  const before=await sourceSnapshot(),server=await serve(),origin='http://127.0.0.1:'+server.address().port,browser=await chromium.launch({headless:true,downloadsPath:scratch,args:['--disable-lcd-text']});
  const qr=await qrcode.toDataURL('SYNTHETIC UI FIXTURE — NO PAYMENT',{width:256,margin:2}),filterIndex=process.argv.indexOf('--filter'),filter=filterIndex>=0?process.argv[filterIndex+1]:process.argv.find(v=>v.startsWith('--filter='))?.slice(9)||process.env.DRIVEKEY_UI_TEST_FILTER;
  try{for(const suite of suites.filter(s=>!filter||s.name.includes(filter))){const context=await browser.newContext({viewport:{width:1440,height:1000},reducedMotion:'reduce'}),page=await context.newPage(),errors=[],requests=[];const started=Date.now();let result;
      page.on('pageerror',e=>errors.push(e.message));
      await context.route('**/*',route=>{const url=route.request().url();if(url.startsWith(origin+'/')||url.startsWith('data:'))return route.continue();requests.push(url);return route.abort('blockedbyclient');});
      await context.addInitScript(installFixture,{...suite.options,qr,passphrase});
      if(suite.options.recovery)await context.addInitScript(()=>window.__fixture.patch({recoveryRequired:true,canRecover:true,error:'Saved wallet list is damaged. Your vault files are unchanged.'}));
      try{await page.goto(origin,{waitUntil:'load'});await page.waitForFunction(()=>document.body.dataset.ready==='true',{timeout:10000});await suite.run(page);assert.deepEqual(errors,[],'Renderer errors');assert.deepEqual(requests,[],'Unexpected external request');const state=await snapshot(page);result={name:suite.name,screens:suite.screens,passed:true,durationMs:Date.now()-started,apiCalls:state.calls,visualAudit:await auditVisuals(page),scope:'actual renderer with synthetic finite preload; no main process or cryptographic signing'};}
      catch(error){await page.screenshot({path:path.join(output,'fixture-FAIL-'+suite.name+'.png'),fullPage:true}).catch(()=>{});result={name:suite.name,screens:suite.screens,passed:false,durationMs:Date.now()-started,error:error.stack,pageErrors:errors,externalRequests:requests};}
      results.push(result);console.log((result.passed?'PASS ':'FAIL ')+suite.name+(result.error?' '+result.error.split('\n')[0]:''));await context.close();
  }}finally{await browser.close();await new Promise(r=>server.close(r));}
  const report={checkedAt:new Date().toISOString(),scope:'Renderer fixture suite only; synthetic data, no keys, no main process, no chain execution',candidate:path.basename(candidate),selectedSuiteOnly:Boolean(filter),passed:results.every(r=>r.passed),passedTests:results.filter(r=>r.passed).length,failedTests:results.filter(r=>!r.passed).length,coveredScreenGroups:[...new Set(results.filter(r=>r.passed).flatMap(r=>r.screens))].sort((a,b)=>a-b),missingScreenGroups:Array.from({length:24},(_,i)=>i+1).filter(n=>!results.some(r=>r.passed&&r.screens.includes(n))),results};
  report.screenCoverageComplete=report.missingScreenGroups.length===0;report.pixelContrast=pixelMeasurements;
  report.scratch=scratch;report.sourceFiles=await sourceSnapshot();report.sourceStable=JSON.stringify(before)===JSON.stringify(report.sourceFiles);if(!report.sourceStable)report.passed=false;
  await fs.writeFile(path.join(output,'RENDERER-FIXTURE-REPORT.json'),JSON.stringify(report,null,2)+'\n');if(!report.passed)process.exitCode=1;
}
main().catch(e=>{console.error(e);process.exitCode=1;});
